package com.inventory.model;

/**
 * Model representing predicted demand generated by ML model.
 */
public class DemandPrediction {
    private int productId;
    private String productName;
    private double predictedDailyDemand;
    private int forecastDays; // Days ahead
    private double totalExpectedDemand;
    private String method; // E.g., "Smile OLS Regression", "Trend Extrapolation"

    public DemandPrediction() {}

    public DemandPrediction(int productId, String productName, double predictedDailyDemand, int forecastDays, String method) {
        this.productId = productId;
        this.productName = productName;
        this.predictedDailyDemand = Math.max(0.0, predictedDailyDemand);
        this.forecastDays = forecastDays;
        this.totalExpectedDemand = this.predictedDailyDemand * forecastDays;
        this.method = method;
    }

    public int getProductId() {
        return productId;
    }

    public String getProductName() {
        return productName;
    }

    public double getPredictedDailyDemand() {
        return predictedDailyDemand;
    }

    public int getForecastDays() {
        return forecastDays;
    }

    public double getTotalExpectedDemand() {
        return totalExpectedDemand;
    }

    public String getMethod() {
        return method;
    }

    @Override
    public String toString() {
        return String.format("DemandPrediction [%s: Daily=%.2f units | Horizon=%d days | Total Expected=%.1f units (Method: %s)]",
                productName, predictedDailyDemand, forecastDays, totalExpectedDemand, method);
    }
}
